(function() {
    'use strict';

    class ProductionSchedulingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Production Scheduling: La Línea en Marcha';
            this.version = '1.1.0';
            this.BOTTLENECK_RATE = 75;
            this.CUTTING_RATE = 120;
            this.FINISHING_RATE = 110;
            this.BASE_HOURS = 8;
            this.OT_HOURS = 4;
            this.OT_COST = 6200;
            this.CHANGEOVER = {
                none_any:       { time: 5 / 60,  cost: 200  },
                same:           { time: 5 / 60,  cost: 200  },
                work_to_school: { time: 45 / 60, cost: 2400 },
                school_to_work: { time: 30 / 60, cost: 1600 }
            };
            this.UNIT_COST  = { work: 285, school: 195 };
            this.UNIT_PRICE = { work: 420, school: 310 };
            this.RUSH_PENALTY = 8000;
            this.RUSH_REVENUE_LOSS = 62000;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    currentProduct: 'none',
                    orderA_remaining: 500,
                    orderA_delivered: false,
                    orderA_late: false,
                    orderB_remaining: 350,
                    orderB_delivered: false,
                    orderB_late: false,
                    orderC_remaining: 250,
                    orderC_delivered: false,
                    orderC_late: false,
                    orderD_remaining: 200,
                    orderD_delivered: false,
                    orderD_late: false,
                    orderD_visible: false,
                    orderD_accepted: false,
                    orderD_declined: false,
                    workStock: 0,
                    schoolStock: 0,
                    totalRevenue: 0,
                    totalVariableCost: 0,
                    totalChangeoverCost: 0,
                    totalOvertimeCost: 0,
                    totalPenaltyCost: 0,
                    totalUnitsProduced: 0,
                    totalAllocated: 0,
                    onTimeCount: 0,
                    lateCount: 0,
                    changeovers: 0,
                    throughputHistory: [],
                    costHistory: [],
                    profitHistory: [],
                    revenueHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    product: 'work',
                    overtime: false,
                    rushResponse: 'accept'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var productEl = document.getElementById('productSelect');
            if (productEl) decisions.product = productEl.value;

            var otEl = document.getElementById('overtimeCheck');
            if (otEl) decisions.overtime = otEl.checked;

            var rushEl = document.getElementById('rushResponse');
            if (rushEl) decisions.rushResponse = rushEl.value;

            if (!decisions.product || (decisions.product !== 'work' && decisions.product !== 'school')) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('product_warning'), 'warning'
                );
                return false;
            }
            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var day = state.currentPeriod;

            // --- Changeover ---
            var coKey = 'same';
            if (ds.currentProduct === 'none') {
                coKey = 'none_any';
            } else if (ds.currentProduct !== d.product) {
                coKey = ds.currentProduct + '_to_' + d.product;
                ds.changeovers++;
            }
            var co = this.CHANGEOVER[coKey] || this.CHANGEOVER.same;
            var changeoverTime = co.time;
            var changeoverCost = co.cost;

            // --- Hours ---
            var totalHours = this.BASE_HOURS;
            var overtimeCost = 0;
            if (d.overtime) {
                totalHours += this.OT_HOURS;
                overtimeCost = this.OT_COST;
            }

            // --- Rush order logic (day 3) ---
            var rushCost = 0;
            var rushExtraHours = 0;
            if (day === 3 && !ds.orderD_visible) {
                ds.orderD_visible = true;
                if (d.rushResponse === 'accept') {
                    ds.orderD_accepted = true;
                } else if (d.rushResponse === 'penalty') {
                    ds.orderD_accepted = true;
                    ds.orderD_late = true;
                    rushCost = this.RUSH_PENALTY;
                } else if (d.rushResponse === 'overtime') {
                    ds.orderD_accepted = true;
                    rushExtraHours = this.OT_HOURS;
                    overtimeCost += this.OT_COST;
                } else {
                    ds.orderD_declined = true;
                    ds.orderD_accepted = false;
                    ds.orderD_remaining = 0;
                }
            }

            totalHours += rushExtraHours;

            // --- Production ---
            var effectiveHours = Math.max(0, totalHours - changeoverTime);
            var unitsProduced = Math.round(effectiveHours * this.BOTTLENECK_RATE);

            // Queue visualization data
            var queueBeforeSewing = Math.round(effectiveHours * (this.CUTTING_RATE - this.BOTTLENECK_RATE));
            var queueBeforeFinishing = 0;

            // --- Cost ---
            var unitCost = this.UNIT_COST[d.product];
            var unitPrice = this.UNIT_PRICE[d.product];
            var variableCost = unitsProduced * unitCost;

            // --- Allocate to orders ---
            var available = unitsProduced;
            if (d.product === 'work') {
                available += ds.workStock;
            } else {
                available += ds.schoolStock;
            }

            var allocated = 0;

            if (d.product === 'work') {
                // Priority: C (due 4) then A (due 5)
                if (ds.orderC_remaining > 0) {
                    var forC = Math.min(available, ds.orderC_remaining);
                    ds.orderC_remaining -= forC;
                    available -= forC;
                    allocated += forC;
                }
                if (ds.orderA_remaining > 0) {
                    var forA = Math.min(available, ds.orderA_remaining);
                    ds.orderA_remaining -= forA;
                    available -= forA;
                    allocated += forA;
                }
                ds.workStock = available;
                ds.schoolStock = ds.schoolStock;
            } else {
                // Priority: B (due 3) then D (due 5)
                if (ds.orderB_remaining > 0) {
                    var forB = Math.min(available, ds.orderB_remaining);
                    ds.orderB_remaining -= forB;
                    available -= forB;
                    allocated += forB;
                }
                if (ds.orderD_accepted && ds.orderD_remaining > 0) {
                    var forD = Math.min(available, ds.orderD_remaining);
                    ds.orderD_remaining -= forD;
                    available -= forD;
                    allocated += forD;
                }
                ds.schoolStock = available;
                ds.workStock = ds.workStock;
            }

            var revenue = allocated * unitPrice;

            // --- Due date checks ---
            // Order B: due day 3
            if (day >= 3 && !ds.orderB_delivered && !ds.orderB_late) {
                if (ds.orderB_remaining <= 0) {
                    ds.orderB_delivered = true;
                    ds.onTimeCount++;
                } else {
                    ds.orderB_late = true;
                    ds.lateCount++;
                }
            }
            // Order C: due day 4
            if (day >= 4 && !ds.orderC_delivered && !ds.orderC_late) {
                if (ds.orderC_remaining <= 0) {
                    ds.orderC_delivered = true;
                    ds.onTimeCount++;
                } else {
                    ds.orderC_late = true;
                    ds.lateCount++;
                }
            }
            // Order A: due day 5
            if (day >= 5 && !ds.orderA_delivered && !ds.orderA_late) {
                if (ds.orderA_remaining <= 0) {
                    ds.orderA_delivered = true;
                    ds.onTimeCount++;
                } else {
                    ds.orderA_late = true;
                    ds.lateCount++;
                }
            }
            // Order D: due day 5
            if (day >= 5 && ds.orderD_accepted && !ds.orderD_delivered && !ds.orderD_late) {
                if (ds.orderD_remaining <= 0) {
                    ds.orderD_delivered = true;
                    ds.onTimeCount++;
                } else {
                    ds.orderD_late = true;
                    ds.lateCount++;
                }
            }

            // --- Totals ---
            var totalDayCost = variableCost + changeoverCost + overtimeCost + rushCost;
            var dayProfit = revenue - totalDayCost;

            ds.currentProduct = d.product;
            ds.totalRevenue += revenue;
            ds.totalVariableCost += variableCost;
            ds.totalChangeoverCost += changeoverCost;
            ds.totalOvertimeCost += overtimeCost;
            ds.totalPenaltyCost += rushCost;
            ds.totalUnitsProduced += unitsProduced;
            ds.totalAllocated += allocated;

            ds.throughputHistory.push(unitsProduced);
            ds.costHistory.push(totalDayCost);
            ds.profitHistory.push(dayProfit);
            ds.revenueHistory.push(revenue);

            // --- Update queue display ---
            var qSewing = document.getElementById('queueSewing');
            if (qSewing) qSewing.textContent = queueBeforeSewing;
            var qFinishing = document.getElementById('queueFinishing');
            if (qFinishing) qFinishing.textContent = queueBeforeFinishing;

            // --- Update briefing for next day ---
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return {
                period: day,
                product: d.product,
                unitsProduced: unitsProduced,
                allocated: allocated,
                revenue: revenue,
                variableCost: variableCost,
                changeoverCost: changeoverCost,
                overtimeCost: overtimeCost,
                rushCost: rushCost,
                totalCost: totalDayCost,
                profit: dayProfit,
                queueSewing: queueBeforeSewing,
                orderA_rem: ds.orderA_remaining,
                orderB_rem: ds.orderB_remaining,
                orderC_rem: ds.orderC_remaining,
                orderD_rem: ds.orderD_remaining
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                function(v) { return 'MXN $' + Math.round(v).toLocaleString(); });
            uiManager.bind('costDisplay', 'domainState.totalVariableCost',
                function(v) {
                    var ds = window.mySimulation.state.domainState;
                    var total = (ds.totalVariableCost || 0) + (ds.totalChangeoverCost || 0) + (ds.totalOvertimeCost || 0) + (ds.totalPenaltyCost || 0);
                    return 'MXN $' + Math.round(total).toLocaleString();
                });
            uiManager.bind('unitsDisplay', 'domainState.totalAllocated',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('ontimeDisplay', 'domainState.onTimeCount',
                function(v) {
                    var ds = window.mySimulation.state.domainState;
                    var total = (ds.onTimeCount || 0) + (ds.lateCount || 0);
                    if (total === 0) return '--';
                    return Math.round((ds.onTimeCount / total) * 100) + '%';
                });
        }

        getChartConfig() {
            return {
                throughputChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_units'),
                            data: [],
                            backgroundColor: 'rgba(21,101,192,0.7)',
                            borderColor: '#1565C0',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_throughput_title') }
                        },
                        scales: { y: { beginAtZero: true } }
                    }
                },
                costChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_revenue'),
                                data: [],
                                borderColor: '#2E7D32',
                                backgroundColor: 'rgba(46,125,50,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            },
                            {
                                label: this._t('chart_cost'),
                                data: [],
                                borderColor: '#C62828',
                                backgroundColor: 'rgba(198,40,40,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_cost_title') }
                        },
                        scales: { y: { beginAtZero: true } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.throughputHistory.map(function(_, i) {
                return window.mySimulation.t('dayname_' + (i + 1)) || ('D' + (i + 1));
            });
            return {
                throughputChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.throughputHistory }]
                },
                costChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.costHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastState = history[history.length - 1];
            var ds = lastState.domainState || {};

            var totalOrders = (ds.onTimeCount || 0) + (ds.lateCount || 0);
            var onTimeRate = totalOrders > 0 ? ((ds.onTimeCount || 0) / totalOrders) * 100 : 0;

            var totalCost = (ds.totalVariableCost || 0) + (ds.totalChangeoverCost || 0) + (ds.totalOvertimeCost || 0) + (ds.totalPenaltyCost || 0);
            var totalAlloc = ds.totalAllocated || 1;
            var costPerUnit = totalCost / totalAlloc;

            var theoreticalMax = 75 * 8 * 5;
            var throughputEff = ((ds.totalUnitsProduced || 0) / theoreticalMax) * 100;

            var maxChangeovers = 4;
            var seqScore = Math.max(0, 1 - ((ds.changeovers || 0) / maxChangeovers));

            var onTimePts = 35 * (onTimeRate / 100);
            var costTarget = 300;
            var costRatio = Math.max(0, Math.min(1, costTarget / Math.max(costPerUnit, 1)));
            var costPts = 30 * costRatio;
            var throughputPts = 20 * Math.min(1, throughputEff / 60);
            var seqPts = 15 * seqScore;

            var totalScore = Math.round(onTimePts + costPts + throughputPts + seqPts);

            var performanceKey = 'perf_disorder';
            if (totalScore >= 80) { performanceKey = 'perf_expert'; }
            else if (totalScore >= 65) { performanceKey = 'perf_competent'; }
            else if (totalScore >= 50) { performanceKey = 'perf_learning'; }
            var performance = this._t(performanceKey);

            var insights = [];
            if (onTimeRate >= 75) insights.push(window.mySimulation.t('insight_good_delivery') || 'Strong on-time delivery performance.');
            if (onTimeRate < 50) insights.push(window.mySimulation.t('insight_poor_delivery') || 'Focus on meeting due dates — prioritize urgent orders.');
            if ((ds.changeovers || 0) >= 3) insights.push(window.mySimulation.t('insight_many_changeovers') || 'Frequent product changes increased setup costs. Consider batching.');
            if ((ds.changeovers || 0) <= 1) insights.push(window.mySimulation.t('insight_few_changeovers') || 'Good changeover management kept setup costs low.');
            if (throughputEff > 50) insights.push(window.mySimulation.t('insight_good_throughput') || 'Solid throughput — the bottleneck was well utilized.');
            if (throughputEff <= 30) insights.push(window.mySimulation.t('insight_low_throughput') || 'Low throughput — consider overtime or reducing changeover frequency.');

            return {
                score: totalScore,
                onTimeRate: Math.round(onTimeRate),
                costPerUnit: Math.round(costPerUnit),
                throughputEfficiency: Math.round(throughputEff),
                performance: performance,
                performanceKey: performanceKey,
                totalRevenue: ds.totalRevenue || 0,
                totalCost: totalCost,
                netProfit: (ds.totalRevenue || 0) - totalCost,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var day = state.currentPeriod;
            var ds = state.domainState;

            if (results.changeoverCost > 200) {
                return window.mySimulation.t('hint_changeover');
            }
            if (day === 2 && ds.orderB_remaining > 0 && state.decisions.product === 'work') {
                return window.mySimulation.t('hint_orderB_urgent');
            }
            if (day === 3 && ds.orderC_remaining > 0 && state.decisions.product === 'school') {
                return window.mySimulation.t('hint_orderC_urgent');
            }
            if (results.queueSewing > 200) {
                return window.mySimulation.t('hint_bottleneck_queue');
            }
            if (results.profit < 0) {
                return window.mySimulation.t('hint_loss');
            }
            return null;
        }

